     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION SUMSQ,NORMINV
      INTEGER I,J,K
      DOUBLE PRECISION CURTIM,Q(5),QN(5),U(5),CNK(5,3,3),CNB(5,3,3)
      DOUBLE PRECISION RNK(5,3),VNK(5,3),WK(5,3),RNB(5,3),VNB(5,3),WB(5,
     & 3),WBRCOM(5,3),COM(3),RNKG(3)
