     & (5,3,3)
      DOUBLE PRECISION WKK(5,3),VKK(5,3),DIK(5,3),RPP(5,3),RPK(5,3),RIK(
     & 5,3),RIK2(5,3)
      DOUBLE PRECISION RPRI(5,3),WIK(5,3),VIK(5,3),WIRK(5,3),RKWKK(5,3),
     & WKRPK(5,3),VIKWKR(5,3)
      DOUBLE PRECISION PERR(11),VERR(11),AERR(11),MULT(11),UFK(5,3),UTK(
     & 5,3),MFK(5,3),MTK(5,3)
