     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      INTEGER I,J,QCHG,UCHG
      DOUBLE PRECISION E1,E2,E3,E4
C
      IF ((ROUSTATE .NE. 1) .AND. (ROUSTATE .NE. 2) .AND. (ROUSTATE
     &  .NE. 3)) THEN
        CALL SDSETERR(8,22)
        RETURN
      ENDIF
      IF (ROUSTATE .EQ. 1) THEN
        DO 50 I=1,5
          IF (PRESQ(I) .EQ. 1) THEN
            CALL SDSETERR(8,31)
          ENDIF
50      CONTINUE
        DO 60 I=1,2
          IF (LPRESQ(I) .EQ. 1) THEN
            CALL SDSETERR(8,40)
          ENDIF
60      CONTINUE
      ENDIF
C
C See if time or any qs have changed since last call
C
      IF ((ROUSTATE .NE. 1) .AND. (TIMEIN .EQ. CURTIM)) THEN
        QCHG= 0
        DO 65 I=1,5
          IF (QIN(I) .NE. Q(I)) THEN
            QCHG= 1
            GOTO 70
          ENDIF
65      CONTINUE
70      CONTINUE
      ELSE
        QCHG= 1
      ENDIF
C
C If time and qs are unchanged, check us
C
      IF (QCHG .EQ. 0) THEN
        UCHG= 0
        DO 75 I=1,5
          IF (UIN(I) .NE. U(I)) THEN
            UCHG= 1
            GOTO 80
          ENDIF
75      CONTINUE
80      CONTINUE
      ELSE
        UCHG= 1
      ENDIF
      CURTIM= TIMEIN
      ROUSTATE= 2
      IF (QCHG .EQ. 0) THEN
C goto skipqs
        GOTO 190
      ENDIF
C
C Position-related variables need to be computed
C
      VPKFLG= 0
      MMFLG= 0
      MMLDUFLG= 0
      WWFLG= 0
      DO 100 I=1,5
        Q(I)= QIN(I)
100   CONTINUE
C
C Compute sines and cosines of q
C
      S2= DSIN(Q(2))
      C2= DCOS(Q(2))
      S3= DSIN(Q(3))
      C3= DCOS(Q(3))
      S5= DSIN(Q(5))
      C5= DCOS(Q(5))
C
C Compute across-axis direction cosines Cik
C
C
C Compute across-joint direction cosines Cib
C
C
C Compute gravity
C
C
C Compute cnk & cnb (direction cosines in N)
C
      CNK(3,1,1)= ((C2*C3)-(S2*S3))
      CNK(3,1,2)= -((S2*C3)+(S3*C2))
      CNK(3,2,1)= ((S2*C3)+(S3*C2))
      CNK(3,2,2)= ((C2*C3)-(S2*S3))
      CNB(1,1,1)= 1D0
      CNB(1,1,2)= 0D0
      CNB(1,1,3)= 0D0
      CNB(1,2,1)= 0D0
      CNB(1,2,2)= 1D0
      CNB(1,2,3)= 0D0
      CNB(1,3,1)= 0D0
      CNB(1,3,2)= 0D0
      CNB(1,3,3)= 1D0
      CNB(2,1,1)= C2
      CNB(2,1,2)= -S2
      CNB(2,1,3)= 0D0
      CNB(2,2,1)= S2
      CNB(2,2,2)= C2
      CNB(2,2,3)= 0D0
      CNB(2,3,1)= 0D0
      CNB(2,3,2)= 0D0
      CNB(2,3,3)= 1D0
      CNB(3,1,1)= CNK(3,1,1)
      CNB(3,1,2)= CNK(3,1,2)
      CNB(3,1,3)= 0D0
      CNB(3,2,1)= CNK(3,2,1)
      CNB(3,2,2)= CNK(3,2,2)
      CNB(3,2,3)= 0D0
      CNB(3,3,1)= 0D0
      CNB(3,3,2)= 0D0
      CNB(3,3,3)= 1D0
      CNB(4,1,1)= CNK(3,1,1)
      CNB(4,1,2)= CNK(3,1,2)
      CNB(4,1,3)= 0D0
      CNB(4,2,1)= CNK(3,2,1)
      CNB(4,2,2)= CNK(3,2,2)
      CNB(4,2,3)= 0D0
      CNB(4,3,1)= 0D0
      CNB(4,3,2)= 0D0
      CNB(4,3,3)= 1D0
      CNB(5,1,1)= C5
      CNB(5,1,2)= -S5
      CNB(5,1,3)= 0D0
      CNB(5,2,1)= S5
      CNB(5,2,2)= C5
      CNB(5,2,3)= 0D0
      CNB(5,3,1)= 0D0
      CNB(5,3,2)= 0D0
      CNB(5,3,3)= 1D0
C
C Compute Cio (dircos btw loop jt connected bodies)
C
      CIO(2,1,1)= ((CNK(3,1,1)*C5)+(CNK(3,2,1)*S5))
      CIO(2,1,2)= ((CNK(3,1,2)*C5)+(CNK(3,2,2)*S5))
      CIO(2,2,1)= ((CNK(3,2,1)*C5)-(CNK(3,1,1)*S5))
      CIO(2,2,2)= ((CNK(3,2,2)*C5)-(CNK(3,1,2)*S5))
C
C Compute q-related auxiliary variables
C
      RPK(4,2)= (Q(4)-.265D0)
      RIK(5,1)= ((.45D0*S5)-(.1D0*C5))
      RIK(5,2)= (((.1D0*S5)+(.45D0*C5))-.05D0)
C
C Compute rnk & rnb (mass center locations in N)
C
      RNK(3,2)= (.25D0+(.1D0*S2))
      RNK(4,1)= ((.1D0*C2)+(CNK(3,1,2)*RPK(4,2)))
      RNK(4,2)= (RNK(3,2)+(CNK(3,2,2)*RPK(4,2)))
      RNK(5,1)= ((.05D0*S5)-.1D0)
      RNK(5,2)= (.45D0-(.05D0*C5))
      RNB(1,1)= Q(1)
      RNB(1,2)= 0D0
      RNB(1,3)= 0D0
      RNB(2,1)= 0D0
      RNB(2,2)= .25D0
      RNB(2,3)= 0D0
      RNB(3,1)= (.1D0*C2)
      RNB(3,2)= RNK(3,2)
      RNB(3,3)= 0D0
      RNB(4,1)= RNK(4,1)
      RNB(4,2)= RNK(4,2)
      RNB(4,3)= 0D0
      RNB(5,1)= RNK(5,1)
      RNB(5,2)= RNK(5,2)
      RNB(5,3)= 0D0
C
C Compute com (system mass center location in N)
C
      COM(1)= (.0424088210347752D0*((1.81D0*RNK(5,1))+((4.54D0*RNK(4,1))
     & +((.136D0*C2)+(15.87D0*Q(1))))))
      COM(2)= (.0424088210347752D0*((1.81D0*RNK(5,2))+((1.36D0*RNK(3,2))
     & +(4.54D0*RNK(4,2)))))
      COM(3)= 0D0
C
C Compute loop joint q-related temps
C
      VT6(1,1)= (Q(1)-RNK(4,1))
      VT10C(1,1)= -(VT6(1,1)+(.265D0*CNK(3,1,2)))
      VT10C(1,2)= (RNK(4,2)-(.265D0*CNK(3,2,2)))
      VT6(2,1)= (RNK(5,1)-RNK(4,1))
      VT6(2,2)= (RNK(5,2)-RNK(4,2))
      VT10C(2,1)= ((.265D0*CIO(2,1,2))-((VT6(2,1)*C5)+(VT6(2,2)*S5)))
      VT10C(2,2)= ((.265D0*CIO(2,2,2))-((VT6(2,2)*C5)-(VT6(2,1)*S5)))
      VT11(2,2)= -(.05D0+VT10C(2,2))
C
C Compute dircos inside loop joints
C
C
C Decompose loop joint dircos into Euler angles or parameters
C
      E1= DATAN2(CNK(3,2,1),CNK(3,1,1))
      EUL1(1)= E1
      E1= DATAN2(CIO(2,2,1),CIO(2,1,1))
      EUL1(2)= E1
      CEUL1(1)= DCOS(EUL1(1))
      CEUL1(2)= DCOS(EUL1(2))
      SEUL1(1)= DSIN(EUL1(1))
      SEUL1(2)= DSIN(EUL1(2))
C
C Compute constraint position errors
C
C skipqs
190   CONTINUE
      IF (UCHG .EQ. 0) THEN
C goto skipus
        GOTO 290
      ENDIF
C
C Velocity-related variables need to be computed
C
      INERFLG= 0
      DO 200 I=1,5
        U(I)= UIN(I)
200   CONTINUE
C
C Compute u-related auxiliary variables
C
C
C Compute wk & wb (angular velocities)
C
      WK(3,3)= (U(2)+U(3))
      WB(1,1)= 0D0
      WB(1,2)= 0D0
      WB(1,3)= 0D0
      WB(2,1)= 0D0
      WB(2,2)= 0D0
      WB(2,3)= U(2)
      WB(3,1)= 0D0
      WB(3,2)= 0D0
      WB(3,3)= WK(3,3)
      WB(4,1)= 0D0
      WB(4,2)= 0D0
      WB(4,3)= WK(3,3)
      WB(5,1)= 0D0
      WB(5,2)= 0D0
      WB(5,3)= U(5)
C
C Compute auxiliary variables involving wk
C
      WKRPK(4,1)= -(RPK(4,2)*WK(3,3))
C
C Compute temporaries for use in SDRHS
C
      W2W2(2)= (U(2)*U(2))
      W2W2(3)= (WK(3,3)*WK(3,3))
      W2W2(4)= (WK(3,3)*WK(3,3))
      W2W2(5)= (U(5)*U(5))
C
C Compute vnk & vnb (mass center linear velocities in N)
C
      VNK(3,1)= -(.1D0*(U(2)*S2))
      VNK(3,2)= (.1D0*(U(2)*C2))
      VNK(4,1)= (VNK(3,1)+((CNK(3,1,1)*WKRPK(4,1))+(CNK(3,1,2)*U(4))))
      VNK(4,2)= (VNK(3,2)+((CNK(3,2,1)*WKRPK(4,1))+(CNK(3,2,2)*U(4))))
      VNK(5,1)= (.05D0*(U(5)*C5))
      VNK(5,2)= (.05D0*(U(5)*S5))
      VNB(1,1)= U(1)
      VNB(1,2)= 0D0
      VNB(1,3)= 0D0
      VNB(2,1)= 0D0
      VNB(2,2)= 0D0
      VNB(2,3)= 0D0
      VNB(3,1)= VNK(3,1)
      VNB(3,2)= VNK(3,2)
      VNB(3,3)= 0D0
      VNB(4,1)= VNK(4,1)
      VNB(4,2)= VNK(4,2)
      VNB(4,3)= 0D0
      VNB(5,1)= VNK(5,1)
      VNB(5,2)= VNK(5,2)
      VNB(5,3)= 0D0
C
C Compute loop joint u-related temps
C
      VT9(1,1)= (U(1)-VNK(4,1))
      VT12(1,1)= (VT9(1,1)-(.265D0*(CNK(3,1,1)*WK(3,3))))
      VT12(1,2)= -(VNK(4,2)+(.265D0*(CNK(3,2,1)*WK(3,3))))
      VT9(2,1)= (VNK(5,1)-VNK(4,1))
      VT9(2,2)= (VNK(5,2)-VNK(4,2))
      VT12(2,1)= (((.05D0*U(5))+(.265D0*(CIO(2,1,1)*WK(3,3))))+((
     & VT9(2,1)*C5)+(VT9(2,2)*S5)))
      VT12(2,2)= ((.265D0*(CIO(2,2,1)*WK(3,3)))+((VT9(2,2)*C5)-(VT9(2,1)
     & *S5)))
C
C Compute angvel inside loop joints
C
      WOIO(2,3)= (WK(3,3)-U(5))
C
C Compute derivatives of loop joint pseudo-coordinates
C
C
C Compute qdot (kinematical equations)
C
      QDOT(1)= U(1)
      QDOT(2)= U(2)
      QDOT(3)= U(3)
      QDOT(4)= U(4)
      QDOT(5)= U(5)
C
C Compute constraint velocity errors
C
      VERR(9)= (VT12(2,1)+(U(5)*VT11(2,2)))
      VERR(10)= (VT12(2,2)+(U(5)*VT10C(2,1)))
C skipus
290   CONTINUE
C
C Initialize applied forces and torques to zero
C
      DO 310 I=1,5
        DO 300 J=1,3
          UFK(I,J)= 0D0
          UTK(I,J)= 0D0
300     CONTINUE
310   CONTINUE
      DO 320 I=1,5
        UTAU(I)= 0D0
320   CONTINUE
      DO 330 I=1,2
        LTAU(I)= 0D0
330   CONTINUE
      LTAUFLG= 0
      FS0FLG= 0
C
C Initialize prescribed motions
C
      UACC(2)= 0D0
      UVEL(2)= U(2)
      UPOS(2)= Q(2)
C
C Set lqs -- sdpsstate may override some
C
      LQ(1)= EUL1(1)
      LQ(2)= EUL1(2)
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain   58 adds/subtracts/negates
C                      76 multiplies
C                       0 divides
C                     204 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDQDOT(OQDOT)
      DOUBLE PRECISION OQDOT(5)
C
C
C Return position coordinate derivatives for tree joints.
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(63,23)
        RETURN
      ENDIF
      DO 100 I=1,5
        OQDOT(I)= QDOT(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDU2QDOT(UIN,OQDOT)
      DOUBLE PRECISION UIN(5),OQDOT(5)
C
C
C Convert velocities to qdots.
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION CURTIM,Q(5),QN(5),U(5),CNK(5,3,3),CNB(5,3,3)
