      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
C
C Compute effect of loop hinge torques
C
      IF (LTAUFLG .EQ. 0) THEN
C
C Compute forces due to loop taus
C
        LTAUTK(4,3)= (LTAU(1)+LTAU(2))
        LTAUFLG= 1
      ENDIF
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain    1 adds/subtracts/negates
C                       0 multiplies
C                       0 divides
C                       1 assignments
C
C
      RETURN
      END
