      DOUBLE PRECISION CIO(2,3,3),CIBO(2,3,3),CIBOB(2,3,3),EUL1(2),EUL2(
     & 2),EUL3(2),EUL4(2)
      DOUBLE PRECISION EUL1DOT(2),EUL2DOT(2),EUL3DOT(2),EUL4DOT(2),EUL1A
     & (2),EUL2A(2),EUL3A(2)
