     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,CIO,CIBO,CIBOB,LTAU,MLTAU,LACC,
     & LVEL,LPOS,LQ,MLTAUFI,MLTAUFO,MLTAUTI,MLTAUTO,WOIO,WOIOB,OOIOB,
     & EUL1,EUL2,EUL3,EUL4,EUL1DOT,EUL2DOT,EUL3DOT,EUL4DOT,EUL1A,EUL2A,
     & EUL3A,CEUL1,CEUL2,CEUL3,SEUL1,SEUL2,SEUL3,SLI1,SLI2,SLI3,SLI1V,
     & SLI2V,SLI3V,SLI1A,SLI2A,SLI3A,IPIN2X,VT1,VT2,VT2A,VT3,VT4,VT5,VT6
     & ,VT7,VT8,VT9,VT10,VT10A,VT10B,VT10C,VT11,VT12,VT13,VT13A,VT14,
     & VT15,VT16,VT17,VT18,VT19,VT20,VT21,VT22,VT23,VT24,VT25,VT26,VT26A
     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      DOUBLE PRECISION FSTARR(5,3),TSTARR(5,3),OTKR(5,3),ATIR(5,3),ATKR(
     & 5,3)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(61,23)
        RETURN
      ENDIF
C
C Compute forces due to loop-joint hinge torques
C
      CALL SDDOLTAU
C
C Compute multiplier-generated forces
C
      CALL SDMFRC(MULTIN)
C
C Account for inertial accelerations and supplied udots
C
      OTKR(3,3)= (UDOTIN(2)+UDOTIN(3))
      ATIR(3,1)= -(.1D0*(U(2)*U(2)))
      ATKR(3,1)= ((.1D0*(UDOTIN(2)*S3))+(ATIR(3,1)*C3))
      ATKR(3,2)= ((.1D0*(UDOTIN(2)*C3))-(ATIR(3,1)*S3))
      ATKR(4,1)= (ATKR(3,1)-((2D0*(U(4)*WK(3,3)))+(OTKR(3,3)*RPK(4,2))))
      ATKR(4,2)= (UDOTIN(4)+(ATKR(3,2)+(WK(3,3)*WKRPK(4,1))))
      ATKR(5,2)= (.05D0*(U(5)*U(5)))
C
C Accumulate all forces and torques
C
      FSTARR(1,1)= ((MFK(1,1)+UFK(1,1))-(15.87D0*UDOTIN(1)))
      FSTARR(1,2)= (MFK(1,2)+UFK(1,2))
      FSTARR(1,3)= (MFK(1,3)+UFK(1,3))
      FSTARR(3,1)= (UFK(3,1)-(1.36D0*ATKR(3,1)))
      FSTARR(3,2)= (UFK(3,2)-(1.36D0*ATKR(3,2)))
      FSTARR(4,1)= ((MFK(4,1)+UFK(4,1))-(4.54D0*ATKR(4,1)))
      FSTARR(4,2)= ((MFK(4,2)+UFK(4,2))-(4.54D0*ATKR(4,2)))
      FSTARR(4,3)= (MFK(4,3)+UFK(4,3))
      FSTARR(5,1)= ((MFK(5,1)+UFK(5,1))-(.0905D0*UDOTIN(5)))
      FSTARR(5,2)= ((MFK(5,2)+UFK(5,2))-(1.81D0*ATKR(5,2)))
      FSTARR(5,3)= (MFK(5,3)+UFK(5,3))
      TSTARR(1,1)= (MTK(1,1)+UTK(1,1))
      TSTARR(1,2)= (MTK(1,2)+UTK(1,2))
      TSTARR(1,3)= (UTK(1,3)+(MTK(1,3)-LTAU(1)))
      TSTARR(2,3)= (UTK(2,3)-(.68D0*UDOTIN(2)))
      TSTARR(3,3)= (UTK(3,3)-(.00066D0*OTKR(3,3)))
      TSTARR(4,1)= (MTK(4,1)+UTK(4,1))
      TSTARR(4,2)= (MTK(4,2)+UTK(4,2))
      TSTARR(4,3)= ((UTK(4,3)+(LTAUTK(4,3)+MTK(4,3)))-(.10756D0*
     & OTKR(3,3)))
      TSTARR(5,1)= (MTK(5,1)+UTK(5,1))
      TSTARR(5,2)= (MTK(5,2)+UTK(5,2))
      TSTARR(5,3)= ((UTK(5,3)+(MTK(5,3)-LTAU(2)))-(.00156D0*UDOTIN(5)))
C
C Now calculate the torques
C
      CALL SDDOVPK
      TRQOUT(1)= -(FSTARR(1,1)+UTAU(1))
      TRQOUT(2)= -((MTAU(2)+UTAU(2))+((TSTARR(2,3)+(TSTARR(3,3)+(.1D0*((
     & FSTARR(3,1)*S3)+(FSTARR(3,2)*C3)))))+(TSTARR(4,3)+((.1D0*(
     & FSTARR(4,2)*C3))+(FSTARR(4,1)*VPK(2,4,1))))))
      TRQOUT(3)= -(UTAU(3)+(TSTARR(3,3)+(TSTARR(4,3)-(FSTARR(4,1)*
     & RPK(4,2)))))
      TRQOUT(4)= -(FSTARR(4,2)+UTAU(4))
      TRQOUT(5)= -(UTAU(5)+(TSTARR(5,3)+(.05D0*FSTARR(5,1))))
C
C Op counts below do not include called subroutines
C
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain   60 adds/subtracts/negates
C                      33 multiplies
C                       0 divides
C                      34 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDCOMPTRQ(UDOTIN,TRQOUT)
      DOUBLE PRECISION UDOTIN(5),TRQOUT(5)
C
C Compute hinge torques to produce these udots, ignoring constraints
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER I
      DOUBLE PRECISION MULTIN(11)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(60,23)
        RETURN
      ENDIF
      DO 100 I=1,11
        MULTIN(I)= 0D0
100   CONTINUE
      CALL SDFULLTRQ(UDOTIN,MULTIN,TRQOUT)
C
      RETURN
      END
C
      SUBROUTINE SDMULTTRQ(MULTIN,TRQOUT)
      DOUBLE PRECISION MULTIN(11),TRQOUT(5)
C
C Compute hinge trqs which would be produced by these mults.
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(65,23)
        RETURN
      ENDIF
      CALL SDMFRC(MULTIN)
      CALL SDFSMULT
      DO 100 I=1,5
        TRQOUT(I)= FS(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDRHS
C
C
C Generated TIMESTAMP by SD/FAST, Kane's formulation
C (sdfast 2.0 #10001)
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION CURTIM,Q(5),QN(5),U(5),CNK(5,3,3),CNB(5,3,3)
      DOUBLE PRECISION RNK(5,3),VNK(5,3),WK(5,3),RNB(5,3),VNB(5,3),WB(5,
     & 3),WBRCOM(5,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(5,3,3),RIKT(5,3,3),IKO(5,3,3),MKRK(5,3,3),CIB
     & (5,3,3)
      DOUBLE PRECISION WKK(5,3),VKK(5,3),DIK(5,3),RPP(5,3),RPK(5,3),RIK(
     & 5,3),RIK2(5,3)
      DOUBLE PRECISION RPRI(5,3),WIK(5,3),VIK(5,3),WIRK(5,3),RKWKK(5,3),
     & WKRPK(5,3),VIKWKR(5,3)
      DOUBLE PRECISION PERR(11),VERR(11),AERR(11),MULT(11),UFK(5,3),UTK(
     & 5,3),MFK(5,3),MTK(5,3)
      DOUBLE PRECISION UTAU(5),MTAU(5),UACC(5),UVEL(5),UPOS(5)
      DOUBLE PRECISION CIO(2,3,3),CIBO(2,3,3),CIBOB(2,3,3),EUL1(2),EUL2(
     & 2),EUL3(2),EUL4(2)
      DOUBLE PRECISION EUL1DOT(2),EUL2DOT(2),EUL3DOT(2),EUL4DOT(2),EUL1A
     & (2),EUL2A(2),EUL3A(2)
      DOUBLE PRECISION CEUL1(2),CEUL2(2),CEUL3(2),SEUL1(2),SEUL2(2),
     & SEUL3(2),SLI1(2),SLI2(2),SLI3(2)
      DOUBLE PRECISION SLI1V(2),SLI2V(2),SLI3V(2),SLI1A(2),SLI2A(2),
     & SLI3A(2),IPIN2X(2,3)
      DOUBLE PRECISION LTAU(2),MLTAU(2),LACC(2),LVEL(2),LPOS(2),LQ(2)
      DOUBLE PRECISION MLTAUFI(2,3),MLTAUFO(2,3),MLTAUTI(2,3),MLTAUTO(2,
     & 3),WOIO(2,3),WOIOB(2,3),OOIOB(2,3)
      DOUBLE PRECISION VT1(2,3),VT2(2,3),VT2A(2,3),VT3(2,3),VT4(2,3),VT5
     & (2,3),VT6(2,3)
      DOUBLE PRECISION VT7(2,3),VT8(2,3),VT9(2,3),VT10(2,3),VT10A(2,3),
     & VT10B(2,3),VT10C(2,3)
      DOUBLE PRECISION VT11(2,3),VT12(2,3),VT13(2,3),VT13A(2,3),VT14(2,3
     & ),VT15(2,3)
      DOUBLE PRECISION VT16(2,3),VT17(2,3),VT18(2,3),VT19(2,3),VT20(2,3)
     & ,VT21(2,3)
      DOUBLE PRECISION VT22(2,3),VT23(2,3),VT24(2,3),VT25(2,3),VT26(2,3)
     & ,VT26A(2,3),VT27(2,3)
      DOUBLE PRECISION S2,C2,S3,C3,S5,C5
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,CIO,CIBO,CIBOB,LTAU,MLTAU,LACC,
     & LVEL,LPOS,LQ,MLTAUFI,MLTAUFO,MLTAUTI,MLTAUTO,WOIO,WOIOB,OOIOB,
     & EUL1,EUL2,EUL3,EUL4,EUL1DOT,EUL2DOT,EUL3DOT,EUL4DOT,EUL1A,EUL2A,
     & EUL3A,CEUL1,CEUL2,CEUL3,SEUL1,SEUL2,SEUL3,SLI1,SLI2,SLI3,SLI1V,
     & SLI2V,SLI3V,SLI1A,SLI2A,SLI3A,IPIN2X,VT1,VT2,VT2A,VT3,VT4,VT5,VT6
     & ,VT7,VT8,VT9,VT10,VT10A,VT10B,VT10C,VT11,VT12,VT13,VT13A,VT14,
     & VT15,VT16,VT17,VT18,VT19,VT20,VT21,VT22,VT23,VT24,VT25,VT26,VT26A
     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
C
C Compute hinge torques for tree hinges
C
      TAUC(1)= UTAU(1)
      TAUC(2)= (MTAU(2)+UTAU(2))
      TAUC(3)= UTAU(3)
      TAUC(4)= UTAU(4)
      TAUC(5)= UTAU(5)
C
C Compute hinge torques for loop joints
C
      LTAUC(1)= LTAU(1)
      LTAUC(2)= LTAU(2)
      CALL SDDOINER
C
C Compute onk & onb (angular accels in N)
C
      ONKB(3,3)= (UDOT(2)+UDOT(3))
      ONB(1,1)= 0D0
      ONB(1,2)= 0D0
      ONB(1,3)= 0D0
      ONB(2,1)= 0D0
      ONB(2,2)= 0D0
      ONB(2,3)= UDOT(2)
      ONB(3,1)= 0D0
      ONB(3,2)= 0D0
      ONB(3,3)= ONKB(3,3)
      ONB(4,1)= 0D0
      ONB(4,2)= 0D0
      ONB(4,3)= ONKB(3,3)
      ONB(5,1)= 0D0
      ONB(5,2)= 0D0
      ONB(5,3)= UDOT(5)
C
C Compute acceleration dyadics
C
      DYAD(1,1,1)= 0D0
      DYAD(1,1,2)= 0D0
      DYAD(1,1,3)= 0D0
      DYAD(1,2,1)= 0D0
      DYAD(1,2,2)= 0D0
      DYAD(1,2,3)= 0D0
      DYAD(1,3,1)= 0D0
      DYAD(1,3,2)= 0D0
      DYAD(1,3,3)= 0D0
      DYAD(2,1,1)= -W2W2(2)
      DYAD(2,1,2)= -UDOT(2)
      DYAD(2,1,3)= 0D0
      DYAD(2,2,1)= UDOT(2)
      DYAD(2,2,2)= -W2W2(2)
      DYAD(2,2,3)= 0D0
      DYAD(2,3,1)= 0D0
      DYAD(2,3,2)= 0D0
      DYAD(2,3,3)= 0D0
      DYAD(3,1,1)= -W2W2(3)
      DYAD(3,1,2)= -ONKB(3,3)
      DYAD(3,1,3)= 0D0
      DYAD(3,2,1)= ONKB(3,3)
      DYAD(3,2,2)= -W2W2(3)
      DYAD(3,2,3)= 0D0
      DYAD(3,3,1)= 0D0
      DYAD(3,3,2)= 0D0
      DYAD(3,3,3)= 0D0
      DYAD(4,1,1)= -W2W2(4)
      DYAD(4,1,2)= -ONKB(3,3)
      DYAD(4,1,3)= 0D0
      DYAD(4,2,1)= ONKB(3,3)
      DYAD(4,2,2)= -W2W2(4)
      DYAD(4,2,3)= 0D0
      DYAD(4,3,1)= 0D0
      DYAD(4,3,2)= 0D0
      DYAD(4,3,3)= 0D0
      DYAD(5,1,1)= -W2W2(5)
      DYAD(5,1,2)= -UDOT(5)
      DYAD(5,1,3)= 0D0
      DYAD(5,2,1)= UDOT(5)
      DYAD(5,2,2)= -W2W2(5)
      DYAD(5,2,3)= 0D0
      DYAD(5,3,1)= 0D0
      DYAD(5,3,2)= 0D0
      DYAD(5,3,3)= 0D0
C
C Compute ank & anb (mass center linear accels in N)
C
      ANKB(3,1)= (.1D0*(UDOT(2)*S3))
      ANKB(3,2)= (.1D0*(UDOT(2)*C3))
      ANKB(4,1)= (ANKB(3,1)-(ONKB(3,3)*RPK(4,2)))
      ANKB(4,2)= (ANKB(3,2)+UDOT(4))
      ANKATK(3,1)= (ANKB(3,1)+ATK(3,1))
      ANKATK(3,2)= (ANKB(3,2)+ATK(3,2))
      ANK(3,1)= ((ANKATK(3,1)*CNK(3,1,1))+(ANKATK(3,2)*CNK(3,1,2)))
      ANK(3,2)= ((ANKATK(3,1)*CNK(3,2,1))+(ANKATK(3,2)*CNK(3,2,2)))
      ANKATK(4,1)= (ANKB(4,1)+ATK(4,1))
      ANKATK(4,2)= (ANKB(4,2)+ATK(4,2))
      ANK(4,1)= ((ANKATK(4,1)*CNK(3,1,1))+(ANKATK(4,2)*CNK(3,1,2)))
      ANK(4,2)= ((ANKATK(4,1)*CNK(3,2,1))+(ANKATK(4,2)*CNK(3,2,2)))
      ANK(5,1)= ((.05D0*(UDOT(5)*C5))-(ATK(5,2)*S5))
      ANK(5,2)= ((.05D0*(UDOT(5)*S5))+(ATK(5,2)*C5))
      ANB(1,1)= UDOT(1)
      ANB(1,2)= 0D0
      ANB(1,3)= 0D0
      ANB(2,1)= 0D0
      ANB(2,2)= 0D0
      ANB(2,3)= 0D0
      ANB(3,1)= ANK(3,1)
      ANB(3,2)= ANK(3,2)
      ANB(3,3)= 0D0
      ANB(4,1)= ANK(4,1)
      ANB(4,2)= ANK(4,2)
      ANB(4,3)= 0D0
      ANB(5,1)= ANK(5,1)
      ANB(5,2)= ANK(5,2)
      ANB(5,3)= 0D0
C
C Compute loop joint temps
C
      VT17(1,1)= (UDOT(1)-ANK(4,1))
      VT19(1,1)= (VT17(1,1)-(.265D0*((CNK(3,1,1)*ONKB(3,3))+(CNK(3,1,2)*
     & W2W2(4)))))
      VT19(1,2)= -(ANK(4,2)+(.265D0*((CNK(3,2,1)*ONKB(3,3))+(CNK(3,2,2)*
     & W2W2(4)))))
      VT17(2,1)= (ANK(5,1)-ANK(4,1))
      VT17(2,2)= (ANK(5,2)-ANK(4,2))
      VT19(2,1)= (((.05D0*UDOT(5))+(.265D0*((CIO(2,1,1)*ONKB(3,3))+(
     & CIO(2,1,2)*W2W2(4)))))+((VT17(2,1)*C5)+(VT17(2,2)*S5)))
      VT19(2,2)= (((.05D0*W2W2(5))+(.265D0*((CIO(2,2,1)*ONKB(3,3))+(
     & CIO(2,2,2)*W2W2(4)))))+((VT17(2,2)*C5)-(VT17(2,1)*S5)))
      VT24(2,3)= (ONKB(3,3)-UDOT(5))
C
C Compute loop joint accelerations
C
C
C Compute constraint acceleration errors
C
      ROUSTATE= 3
      AERR(9)= ((VT19(2,1)+(2D0*(U(5)*VT12(2,2))))+((UDOT(5)*VT11(2,2))+
     & (VT10C(2,1)*W2W2(5))))
      AERR(10)= ((VT19(2,2)-(2D0*(U(5)*VT12(2,1))))+((UDOT(5)*VT10C(2,1)
     & )-(VT11(2,2)*W2W2(5))))
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain   49 adds/subtracts/negates
C                      45 multiplies
C                       0 divides
C                     107 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDMASSMAT(MMAT)
      DOUBLE PRECISION MMAT(5,5)
C
C Return the system mass matrix (LHS)
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I,J
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(57,23)
        RETURN
      ENDIF
      CALL SDDOMM(57)
      DO 110 I=1,5
        DO 100 J=I,5
          MMAT(I,J)= MM(I,J)
          MMAT(J,I)= MM(I,J)
100     CONTINUE
110   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDFRCMAT(FMAT)
      DOUBLE PRECISION FMAT(5)
C
C Return the system force matrix (RHS), excluding constraints
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      INTEGER I
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(58,23)
        RETURN
      ENDIF
      CALL SDDOFS0
      DO 100 I=1,5
        FMAT(I)= FS0(I)
100   CONTINUE
C
      RETURN
      END
C
      SUBROUTINE SDPSEUDO(LQOUT,LUOUT)
      DOUBLE PRECISION LQOUT(2),LUOUT(2)
C
C
C Return pseudo-coordinates for loop joints.
C
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      DOUBLE PRECISION CURTIM,Q(5),QN(5),U(5),CNK(5,3,3),CNB(5,3,3)
      DOUBLE PRECISION RNK(5,3),VNK(5,3),WK(5,3),RNB(5,3),VNB(5,3),WB(5,
     & 3),WBRCOM(5,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(5,3,3),RIKT(5,3,3),IKO(5,3,3),MKRK(5,3,3),CIB
     & (5,3,3)
      DOUBLE PRECISION WKK(5,3),VKK(5,3),DIK(5,3),RPP(5,3),RPK(5,3),RIK(
     & 5,3),RIK2(5,3)
      DOUBLE PRECISION RPRI(5,3),WIK(5,3),VIK(5,3),WIRK(5,3),RKWKK(5,3),
     & WKRPK(5,3),VIKWKR(5,3)
      DOUBLE PRECISION PERR(11),VERR(11),AERR(11),MULT(11),UFK(5,3),UTK(
     & 5,3),MFK(5,3),MTK(5,3)
      DOUBLE PRECISION UTAU(5),MTAU(5),UACC(5),UVEL(5),UPOS(5)
      DOUBLE PRECISION CIO(2,3,3),CIBO(2,3,3),CIBOB(2,3,3),EUL1(2),EUL2(
     & 2),EUL3(2),EUL4(2)
      DOUBLE PRECISION EUL1DOT(2),EUL2DOT(2),EUL3DOT(2),EUL4DOT(2),EUL1A
     & (2),EUL2A(2),EUL3A(2)
      DOUBLE PRECISION CEUL1(2),CEUL2(2),CEUL3(2),SEUL1(2),SEUL2(2),
     & SEUL3(2),SLI1(2),SLI2(2),SLI3(2)
      DOUBLE PRECISION SLI1V(2),SLI2V(2),SLI3V(2),SLI1A(2),SLI2A(2),
     & SLI3A(2),IPIN2X(2,3)
      DOUBLE PRECISION LTAU(2),MLTAU(2),LACC(2),LVEL(2),LPOS(2),LQ(2)
