      FUNCTION SDCHKBNUM(ROUTINE,BNUM)
      INTEGER ROUTINE,BNUM
      INTEGER SDCHKBNUM
C
C
      IF ((BNUM .LT. 0) .OR. (BNUM .GT. 5)) THEN
        CALL SDSETERR(ROUTINE,15)
        SDCHKBNUM= 1
        RETURN
      ENDIF
      SDCHKBNUM= 0
      RETURN
C
      END
C
      FUNCTION SDCHKJNUM(ROUTINE,JNUM)
      INTEGER ROUTINE,JNUM
      INTEGER SDCHKJNUM
C
C
      IF ((JNUM .LT. 1) .OR. (JNUM .GT. 7)) THEN
        CALL SDSETERR(ROUTINE,16)
        SDCHKJNUM= 1
        RETURN
      ENDIF
      SDCHKJNUM= 0
      RETURN
C
      END
C
      FUNCTION SDCHKUCNUM(ROUTINE,UCNUM)
      INTEGER ROUTINE,UCNUM
      INTEGER SDCHKUCNUM
C
C
      IF ((UCNUM .LT. 1) .OR. (UCNUM .GT. 0)) THEN
        CALL SDSETERR(ROUTINE,21)
        SDCHKUCNUM= 1
        RETURN
      ENDIF
      SDCHKUCNUM= 0
      RETURN
C
      END
C
      FUNCTION SDCHKJAXIS(ROUTINE,JNUM,AXNUM)
      INTEGER ROUTINE,JNUM,AXNUM
      INTEGER SDCHKJAXIS
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      INTEGER MAXAX,SDCHKJNUM
C
      IF (SDCHKJNUM(ROUTINE,JNUM) .NE. 0) THEN
        SDCHKJAXIS= 1
        RETURN
      ENDIF
      IF ((AXNUM .LT. 1) .OR. (AXNUM .GT. 7)) THEN
        CALL SDSETERR(ROUTINE,17)
        SDCHKJAXIS= 1
        RETURN
      ENDIF
      MAXAX= NJNTDOF(JNUM)
      IF ((JTYPE(JNUM) .EQ. 4) .OR. (JTYPE(JNUM) .EQ. 6) .OR. (JTYPE(
     & JNUM) .EQ. 21)) THEN
        MAXAX= MAXAX+1
      ENDIF
      IF (AXNUM .GT. MAXAX) THEN
        CALL SDSETERR(ROUTINE,18)
        SDCHKJAXIS= 1
        RETURN
      ENDIF
      SDCHKJAXIS= 0
      RETURN
C
      END
C
      FUNCTION SDCHKJPIN(ROUTINE,JNUM,PINNO)
      INTEGER ROUTINE,JNUM,PINNO
      INTEGER SDCHKJPIN
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      INTEGER MAXAX,PINOK,SDCHKJNUM
C
      IF (SDCHKJNUM(ROUTINE,JNUM) .NE. 0) THEN
        SDCHKJPIN= 1
        RETURN
      ENDIF
      IF ((PINNO .LT. 1) .OR. (PINNO .GT. 6)) THEN
        CALL SDSETERR(ROUTINE,17)
        SDCHKJPIN= 1
        RETURN
      ENDIF
      IF (NJNTDOF(JNUM) .GE. 3) THEN
        MAXAX= 3
      ELSE
        MAXAX= NJNTDOF(JNUM)
      ENDIF
      IF (JTYPE(JNUM) .EQ. 4) THEN
        MAXAX= 0
      ENDIF
      IF (JTYPE(JNUM) .EQ. 7) THEN
        MAXAX= 1
      ENDIF
      PINOK= 0
      IF (PINNO .LE. MAXAX) THEN
        PINOK= 1
      ENDIF
      IF (JNUM .GT. 5) THEN
        IF (((PINNO .EQ. 1) .AND. ((JTYPE(JNUM) .EQ. 9)))) THEN
          PINOK= 1
        ENDIF
        IF ((PINNO .EQ. 4) .AND. ((JTYPE(JNUM) .EQ. 1) .OR. (JTYPE(JNUM)
     &    .EQ. 5) .OR. (JTYPE(JNUM) .EQ. 7) .OR. (JTYPE(JNUM) .EQ. 9))
     &   ) THEN
          PINOK= 1
        ENDIF
        IF (((PINNO .EQ. 5) .OR. (PINNO .EQ. 6)) .AND. ((JTYPE(JNUM)
     &    .NE. 4) .AND. (JTYPE(JNUM) .NE. 6))) THEN
          PINOK= 1
        ENDIF
      ENDIF
      IF (PINOK .EQ. 0) THEN
        CALL SDSETERR(ROUTINE,18)
        SDCHKJPIN= 1
        RETURN
      ENDIF
      SDCHKJPIN= 0
      RETURN
C
      END
C
      FUNCTION SDINDX(JOINT,AXIS)
      INTEGER JOINT,AXIS
      INTEGER SDINDX
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      INTEGER OFFS,GOTIT
      INTEGER SDCHKJAXIS
C
      IF (SDCHKJAXIS(36,JOINT,AXIS) .NE. 0) THEN
        SDINDX= 1
        RETURN
      ENDIF
      GOTIT= 0
      IF (JTYPE(JOINT) .EQ. 4) THEN
        IF (AXIS .EQ. 4) THEN
          OFFS= BALLQ(JOINT)
          GOTIT= 1
        ENDIF
      ELSE
        IF ((JTYPE(JOINT) .EQ. 6) .OR. (JTYPE(JOINT) .EQ. 21)) THEN
          IF (AXIS .EQ. 7) THEN
            OFFS= BALLQ(JOINT)
            GOTIT= 1
          ENDIF
        ENDIF
      ENDIF
      IF (GOTIT .EQ. 0) THEN
        OFFS= FIRSTQ(JOINT)+AXIS-1
      ENDIF
      SDINDX= OFFS
      RETURN
C
      END
