      DOUBLE PRECISION CEUL1(2),CEUL2(2),CEUL3(2),SEUL1(2),SEUL2(2),
     & SEUL3(2),SLI1(2),SLI2(2),SLI3(2)
      DOUBLE PRECISION SLI1V(2),SLI2V(2),SLI3V(2),SLI1A(2),SLI2A(2),
     & SLI3A(2),IPIN2X(2,3)
      DOUBLE PRECISION LTAU(2),MLTAU(2),LACC(2),LVEL(2),LPOS(2),LQ(2)
      DOUBLE PRECISION MLTAUFI(2,3),MLTAUFO(2,3),MLTAUTI(2,3),MLTAUTO(2,
     & 3),WOIO(2,3),WOIOB(2,3),OOIOB(2,3)
