     & VT15,VT16,VT17,VT18,VT19,VT20,VT21,VT22,VT23,VT24,VT25,VT26,VT26A
     & ,VT27,S2,C2,S3,C3,S5,C5
      INTEGER SDINDX
      INTEGER SDCHKJAXIS
C
      IF (SDCHKJAXIS(10,JOINT,AXIS) .NE. 0) THEN
        RETURN
      ENDIF
      IF (ROUSTATE .NE. 2) THEN
        CALL SDSETERR(10,23)
        RETURN
      ENDIF
      IF (MFRCFLG .NE. 0) THEN
        IF (JOINT .GT. 5) THEN
          MLTAU(SDINDX(JOINT,AXIS))= MLTAU(SDINDX(JOINT,AXIS))+TORQUE
        ELSE
          MTAU(SDINDX(JOINT,AXIS))= MTAU(SDINDX(JOINT,AXIS))+TORQUE
        ENDIF
      ELSE
        FS0FLG= 0
        IF (JOINT .GT. 5) THEN
          LTAU(SDINDX(JOINT,AXIS))= LTAU(SDINDX(JOINT,AXIS))+TORQUE
          LTAUFLG= 0
        ELSE
          UTAU(SDINDX(JOINT,AXIS))= UTAU(SDINDX(JOINT,AXIS))+TORQUE
        ENDIF
      ENDIF
C
      RETURN
      END
