     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(67,23)
        RETURN
      ENDIF
      CALL SDXUDOTM(67,IMULT,OUDOTM)
C
      RETURN
      END
C
      SUBROUTINE SDDERIV(OQDOT,OUDOT)
      DOUBLE PRECISION OQDOT(5),OUDOT(5)
C
C
C This is the derivative section for a 5-body ground-based
C system with 5 hinge degree(s) of freedom.
C 1 of the degrees of freedom may follow prescribed motion.
C There are 11 constraints.
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      DOUBLE PRECISION CURTIM,Q(5),QN(5),U(5),CNK(5,3,3),CNB(5,3,3)
      DOUBLE PRECISION RNK(5,3),VNK(5,3),WK(5,3),RNB(5,3),VNB(5,3),WB(5,
     & 3),WBRCOM(5,3),COM(3),RNKG(3)
      DOUBLE PRECISION CIK(5,3,3),RIKT(5,3,3),IKO(5,3,3),MKRK(5,3,3),CIB
     & (5,3,3)
      DOUBLE PRECISION WKK(5,3),VKK(5,3),DIK(5,3),RPP(5,3),RPK(5,3),RIK(
     & 5,3),RIK2(5,3)
      DOUBLE PRECISION RPRI(5,3),WIK(5,3),VIK(5,3),WIRK(5,3),RKWKK(5,3),
     & WKRPK(5,3),VIKWKR(5,3)
      DOUBLE PRECISION PERR(11),VERR(11),AERR(11),MULT(11),UFK(5,3),UTK(
     & 5,3),MFK(5,3),MTK(5,3)
      DOUBLE PRECISION UTAU(5),MTAU(5),UACC(5),UVEL(5),UPOS(5)
      DOUBLE PRECISION CIO(2,3,3),CIBO(2,3,3),CIBOB(2,3,3),EUL1(2),EUL2(
     & 2),EUL3(2),EUL4(2)
      DOUBLE PRECISION EUL1DOT(2),EUL2DOT(2),EUL3DOT(2),EUL4DOT(2),EUL1A
     & (2),EUL2A(2),EUL3A(2)
      DOUBLE PRECISION CEUL1(2),CEUL2(2),CEUL3(2),SEUL1(2),SEUL2(2),
     & SEUL3(2),SLI1(2),SLI2(2),SLI3(2)
      DOUBLE PRECISION SLI1V(2),SLI2V(2),SLI3V(2),SLI1A(2),SLI2A(2),
     & SLI3A(2),IPIN2X(2,3)
      DOUBLE PRECISION LTAU(2),MLTAU(2),LACC(2),LVEL(2),LPOS(2),LQ(2)
      DOUBLE PRECISION MLTAUFI(2,3),MLTAUFO(2,3),MLTAUTI(2,3),MLTAUTO(2,
     & 3),WOIO(2,3),WOIOB(2,3),OOIOB(2,3)
      DOUBLE PRECISION VT1(2,3),VT2(2,3),VT2A(2,3),VT3(2,3),VT4(2,3),VT5
     & (2,3),VT6(2,3)
      DOUBLE PRECISION VT7(2,3),VT8(2,3),VT9(2,3),VT10(2,3),VT10A(2,3),
     & VT10B(2,3),VT10C(2,3)
      DOUBLE PRECISION VT11(2,3),VT12(2,3),VT13(2,3),VT13A(2,3),VT14(2,3
     & ),VT15(2,3)
      DOUBLE PRECISION VT16(2,3),VT17(2,3),VT18(2,3),VT19(2,3),VT20(2,3)
     & ,VT21(2,3)
      DOUBLE PRECISION VT22(2,3),VT23(2,3),VT24(2,3),VT25(2,3),VT26(2,3)
     & ,VT26A(2,3),VT27(2,3)
      DOUBLE PRECISION S2,C2,S3,C3,S5,C5
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,CIO,CIBO,CIBOB,LTAU,MLTAU,LACC,
     & LVEL,LPOS,LQ,MLTAUFI,MLTAUFO,MLTAUTI,MLTAUTO,WOIO,WOIOB,OOIOB,
     & EUL1,EUL2,EUL3,EUL4,EUL1DOT,EUL2DOT,EUL3DOT,EUL4DOT,EUL1A,EUL2A,
     & EUL3A,CEUL1,CEUL2,CEUL3,SEUL1,SEUL2,SEUL3,SLI1,SLI2,SLI3,SLI1V,
     & SLI2V,SLI3V,SLI1A,SLI2A,SLI3A,IPIN2X,VT1,VT2,VT2A,VT3,VT4,VT5,VT6
     & ,VT7,VT8,VT9,VT10,VT10A,VT10B,VT10C,VT11,VT12,VT13,VT13A,VT14,
     & VT15,VT16,VT17,VT18,VT19,VT20,VT21,VT22,VT23,VT24,VT25,VT26,VT26A
     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION WORKR(11),BB(11),B0(11),V0(11),P0(11)
      INTEGER IWORK(11)
      INTEGER I,J
      DOUBLE PRECISION UDOT0(5),UDOT1(5)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(17,23)
        RETURN
      ENDIF
      IF (STABVELQ .EQ. 1) THEN
        CALL SDSETERR(17,32)
      ENDIF
      IF (STABPOSQ .EQ. 1) THEN
        CALL SDSETERR(17,33)
      ENDIF
      WSIZ= 5
C
C Compute unconstrained equations
C
      CALL SDXUDOT0(17,UDOT0)
      CALL SDRHS
      CALL SDAERR(B0)
      IF (STABVEL  .NE.  0D0) THEN
        CALL SDVERR(V0)
      ENDIF
      IF (STABPOS  .NE.  0D0) THEN
        CALL SDPERR(P0)
      ENDIF
C
C Stabilize constraints using Baumgarte's method
C
      DO 10 I=1,11
        BB(I)= -B0(I)
10    CONTINUE
      IF (STABVEL  .NE.  0D0) THEN
        DO 20 I=1,11
          BB(I)= BB(I)-STABVEL*V0(I)
20      CONTINUE
      ENDIF
      IF (STABPOS  .NE.  0D0) THEN
        DO 30 I=1,11
          BB(I)= BB(I)-STABPOS*P0(I)
30      CONTINUE
      ENDIF
C
C Compute and decompose constraint matrix WW
C
      CALL SDDOWW(17)
C
C Numerically solve for constraint multipliers
C
      DO 75 I=1,11
        MULT(I)= 0D0
75    CONTINUE
      CALL SDQRBSLV(11,11,5,5,WMAP,WMAP,1D-13,WORKR,IWORK,
     & WW,QRAUX,JPVT,BB,MULT,WRANK)
      DO 80 I=1,5
        MULTMAP(I)= 0
80    CONTINUE
      DO 85 I=1,WRANK
        MULTMAP(JPVT(I))= 1
85    CONTINUE
      J= 1
      DO 90 I=1,5
        IF (MULTMAP(I) .NE. 0) THEN
          MULTMAP(J)= WMAP(I)
          J= J+1
        ENDIF
90    CONTINUE
C
C Compute final udots
C
      CALL SDXUDOTM(17,MULT,UDOT1)
      DO 95 I=1,5
        UDOT(I)= UDOT0(I)+UDOT1(I)
95    CONTINUE
      CALL SDRHS
      DO 100 I=1,5
        OQDOT(I)= QDOT(I)
100   CONTINUE
      DO 110 I=1,5
        OUDOT(I)= UDOT(I)
110   CONTINUE
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain   38 adds/subtracts/negates
C                      22 multiplies
C                       0 divides
C                      59 assignments
C
C
      RETURN
      END
