      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
      INTEGER I
      DOUBLE PRECISION UDERRS(5),P0(11)
C
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(16,23)
        RETURN
      ENDIF
      IF (STABPOSQ .EQ. 1) THEN
        CALL SDSETERR(16,33)
      ENDIF
      CALL SDFULLTRQ(EUDOT,EMULTS,UDERRS)
      DO 100 I=1,5
        RESID(I)= EQDOT(I)-QDOT(I)
100   CONTINUE
      DO 200 I=1,5
        RESID(5+I)= UDERRS(I)
200   CONTINUE
      CALL SDVERR(RESID(11))
      IF (STABPOS  .NE.  0D0) THEN
        CALL SDPERR(P0)
        DO 250 I=1,11
          RESID(10+I)= RESID(10+I)+STABPOS*P0(I)
250     CONTINUE
      ENDIF
      DO 350 I=1,5
        UDOT(I)= EUDOT(I)
350   CONTINUE
      DO 375 I=1,11
        MULT(I)= EMULTS(I)
375   CONTINUE
      CALL SDRHS
C
C  Used TIMESTAMP seconds CPU time,
C  TIMESTAMP additional bytes of memory.
C  Equations contain   16 adds/subtracts/negates
C                      11 multiplies
C                       0 divides
C                      37 assignments
C
C
      RETURN
      END
C
      SUBROUTINE SDMULT(OMULTS,OWRANK,OMULTMAP)
      DOUBLE PRECISION OMULTS(11)
      INTEGER OWRANK,OMULTMAP(11)
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
