     & SEUL3(2),SLI1(2),SLI2(2),SLI3(2)
      DOUBLE PRECISION SLI1V(2),SLI2V(2),SLI3V(2),SLI1A(2),SLI2A(2),
     & SLI3A(2),IPIN2X(2,3)
      DOUBLE PRECISION LTAU(2),MLTAU(2),LACC(2),LVEL(2),LPOS(2),LQ(2)
      DOUBLE PRECISION MLTAUFI(2,3),MLTAUFO(2,3),MLTAUTI(2,3),MLTAUTO(2,
     & 3),WOIO(2,3),WOIOB(2,3),OOIOB(2,3)
      DOUBLE PRECISION VT1(2,3),VT2(2,3),VT2A(2,3),VT3(2,3),VT4(2,3),VT5
     & (2,3),VT6(2,3)
      DOUBLE PRECISION VT7(2,3),VT8(2,3),VT9(2,3),VT10(2,3),VT10A(2,3),
     & VT10B(2,3),VT10C(2,3)
      DOUBLE PRECISION VT11(2,3),VT12(2,3),VT13(2,3),VT13A(2,3),VT14(2,3
     & ),VT15(2,3)
      DOUBLE PRECISION VT16(2,3),VT17(2,3),VT18(2,3),VT19(2,3),VT20(2,3)
     & ,VT21(2,3)
      DOUBLE PRECISION VT22(2,3),VT23(2,3),VT24(2,3),VT25(2,3),VT26(2,3)
     & ,VT26A(2,3),VT27(2,3)
      DOUBLE PRECISION S2,C2,S3,C3,S5,C5
      COMMON/SDGSTATE/ CURTIM,Q,QN,U,CNK,CNB,RNKG,RNK,RNB,VNK,VNB,WK,WB,
     & COM,CIK,CIB,RIKT,IKO,MKRK,WKK,VKK,DIK,RPP,RPK,RIK,RIK2,RPRI,WIK,
     & VIK,WIRK,RKWKK,WKRPK,VIKWKR,WBRCOM,PERR,VERR,AERR,MULT,UFK,UTK,
     & UTAU,MFK,MTK,MTAU,UACC,UVEL,UPOS,CIO,CIBO,CIBOB,LTAU,MLTAU,LACC,
     & LVEL,LPOS,LQ,MLTAUFI,MLTAUFO,MLTAUTI,MLTAUTO,WOIO,WOIOB,OOIOB,
     & EUL1,EUL2,EUL3,EUL4,EUL1DOT,EUL2DOT,EUL3DOT,EUL4DOT,EUL1A,EUL2A,
     & EUL3A,CEUL1,CEUL2,CEUL3,SEUL1,SEUL2,SEUL3,SLI1,SLI2,SLI3,SLI1V,
     & SLI2V,SLI3V,SLI1A,SLI2A,SLI3A,IPIN2X,VT1,VT2,VT2A,VT3,VT4,VT5,VT6
     & ,VT7,VT8,VT9,VT10,VT10A,VT10B,VT10C,VT11,VT12,VT13,VT13A,VT14,
     & VT15,VT16,VT17,VT18,VT19,VT20,VT21,VT22,VT23,VT24,VT25,VT26,VT26A
     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION FS0(5),QDOT(5),OTK(5,3),ATK(5,3),AIOIWI(5,3),
     & FSTAR(5,3)
      DOUBLE PRECISION TSTAR(5,3),FSTARK(5,3),TSTARK(5,3),IKWK(5,3),
     & WKIKWK(5,3),GK(5,3),IKBWK(5,3),WKIKBWK(5,3)
      DOUBLE PRECISION W0W0(5),W1W1(5),W2W2(5),W0W1(5),W0W2(5),W1W2(5)
      DOUBLE PRECISION W00W11(5),W00W22(5),W11W22(5),WW(11,11),QRAUX(11)
      DOUBLE PRECISION MM(5,5),MLO(5,5),MDI(5),IKWPK(5,5,3),WORKS(5),
     & WORKSS(5,5)
      DOUBLE PRECISION WPK(5,5,3),VPK(5,5,3),VWRI(5,5,3)
      DOUBLE PRECISION LTAUFK(5,3),LTAUTK(5,3),LTAUC(2),LTCI(2,3),LTC(2,
     & 3),LFCI(2,3),LFC(2,3)
      DOUBLE PRECISION TINB(2,3),TOUTB(2,3),LTAUFI(2,3),LTAUFO(2,3),
     & LTAUTI(2,3),LTAUTO(2,3)
      INTEGER WMAP(11),MULTMAP(11),JPVT(11),WSIZ,WRANK
      COMMON/SDGLHS/ QDOT,OTK,ATK,AIOIWI,FSTAR,TSTAR,FS0,FSTARK,TSTARK,
     & IKWK,IKBWK,WKIKWK,WKIKBWK,GK,W0W0,W1W1,W2W2,W0W1,W0W2,W1W2,W00W11
     & ,W00W22,W11W22,WW,QRAUX,LTAUFK,LTAUTK,LTCI,LTC,LFCI,LFC,TINB,
     & TOUTB,LTAUC,LTAUFI,LTAUFO,LTAUTI,LTAUTO,MM,MLO,MDI,IKWPK,WORKS,
     & WORKSS,WPK,VPK,VWRI,WMAP,MULTMAP,JPVT,WSIZ,WRANK
      DOUBLE PRECISION FS(5),UDOT(5),TAUC(5),DYAD(5,3,3),FC(5,3),TC(5,3)
      DOUBLE PRECISION ANK(5,3),ONK(5,3),ONKB(5,3),AONKRI(5,3),ANKB(5,3)
     & ,ANKATK(5,3),ANB(5,3),ONB(5,3),DYRCOM(5,3)
      DOUBLE PRECISION FFK(5,3),TTK(5,3),FCCIKT(5,3),FFKB(5,3),TTKB(5,3)
      COMMON/SDGRHS/ FS,UDOT,ANK,ANB,ONK,ONB,ONKB,AONKRI,ANKB,ANKATK,
     & DYRCOM,FFK,TTK,FCCIKT,FFKB,TTKB,DYAD,FC,TC,TAUC
      DOUBLE PRECISION TEMP(3000),TMAT1(3,3),TMAT2(3,3),TVEC1(3),TVEC2(3
     & ),TVEC3(3),TVEC4(3),TVEC5(3)
      DOUBLE PRECISION TSC1,TSC2,TSC3
      COMMON/SDGTEMP/ TEMP,TMAT1,TMAT2,TVEC1,TVEC2,TVEC3,TVEC4,TVEC5,
     & TSC1,TSC2,TSC3
C
      IF (ROUSTATE .NE. 3) THEN
        CALL SDSETERR(31,24)
        RETURN
      ENDIF
C
C Compute reaction forces for non-weld tree joints
C
      FFKB(1,1)= (MFK(1,1)+UFK(1,1))
      FFKB(1,2)= (MFK(1,2)+UFK(1,2))
      FFKB(1,3)= (MFK(1,3)+UFK(1,3))
      FFKB(4,1)= (MFK(4,1)+UFK(4,1))
      FFKB(4,2)= (MFK(4,2)+UFK(4,2))
      FFKB(4,3)= (MFK(4,3)+UFK(4,3))
      FFKB(5,1)= (MFK(5,1)+UFK(5,1))
      FFKB(5,2)= (MFK(5,2)+UFK(5,2))
      FFKB(5,3)= (MFK(5,3)+UFK(5,3))
      TTKB(1,1)= (MTK(1,1)+UTK(1,1))
      TTKB(1,2)= (MTK(1,2)+UTK(1,2))
      TTKB(1,3)= (UTK(1,3)+(MTK(1,3)-LTAU(1)))
      TTKB(4,1)= (MTK(4,1)+UTK(4,1))
      TTKB(4,2)= (MTK(4,2)+UTK(4,2))
