     & RNK(5,2))))+((4.54D0*((RNK(4,1)*RNK(4,1))+(RNK(4,2)*RNK(4,2))))+(
     & (1.36D0*((.01D0*(C2*C2))+(RNK(3,2)*RNK(3,2))))+(15.87D0*(Q(1)*
     & Q(1))))))-(23.58D0*((COM(1)*COM(1))+(COM(2)*COM(2))))))
