     & ,VT27,S2,C2,S3,C3,S5,C5
      DOUBLE PRECISION PV(3)
      INTEGER SDCHKBNUM
C
      IF (SDCHKBNUM(22,BODY) .NE. 0) THEN
        RETURN
      ENDIF
      IF ((ROUSTATE .NE. 2) .AND. (ROUSTATE .NE. 3)) THEN
        CALL SDSETERR(22,23)
        RETURN
      ENDIF
      IF (BODY  .EQ.  0) THEN
        VELO(1)= 0D0
        VELO(2)= 0D0
        VELO(3)= 0D0
      ELSE
        PV(1)= WB(BODY,2)*PT(3)-WB(BODY,3)*PT(2)
