      SUBROUTINE SDPIN(JOINT,PINNO,PININ)
      INTEGER JOINT,PINNO
      DOUBLE PRECISION PININ(3)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER LJNUM,ANYQUES,OFFS
      INTEGER SDCHKJPIN
C
      IF (SDCHKJPIN(6,JOINT,PINNO) .NE. 0) THEN
        RETURN
      ENDIF
      ANYQUES= 0
      IF (JOINT  .GT.  5) THEN
        LJNUM= JOINT-5
        IF (PINNO  .EQ.  1) THEN
          IF (INBPIN1Q(LJNUM,1)  .NE.  0) THEN
            INBPIN1(LJNUM,1)= PININ(1)
            INBPIN1Q(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN1Q(LJNUM,2)  .NE.  0) THEN
            INBPIN1(LJNUM,2)= PININ(2)
            INBPIN1Q(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN1Q(LJNUM,3)  .NE.  0) THEN
            INBPIN1(LJNUM,3)= PININ(3)
            INBPIN1Q(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
        IF (PINNO  .EQ.  2) THEN
          IF (INBPIN2Q(LJNUM,1)  .NE.  0) THEN
            INBPIN2(LJNUM,1)= PININ(1)
            INBPIN2Q(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN2Q(LJNUM,2)  .NE.  0) THEN
            INBPIN2(LJNUM,2)= PININ(2)
            INBPIN2Q(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN2Q(LJNUM,3)  .NE.  0) THEN
            INBPIN2(LJNUM,3)= PININ(3)
            INBPIN2Q(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
        IF (PINNO  .EQ.  3) THEN
          IF (INBPIN3Q(LJNUM,1)  .NE.  0) THEN
            INBPIN3(LJNUM,1)= PININ(1)
            INBPIN3Q(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN3Q(LJNUM,2)  .NE.  0) THEN
            INBPIN3(LJNUM,2)= PININ(2)
            INBPIN3Q(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (INBPIN3Q(LJNUM,3)  .NE.  0) THEN
            INBPIN3(LJNUM,3)= PININ(3)
            INBPIN3Q(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
        IF (PINNO  .EQ.  4) THEN
          IF (INBREFQ(LJNUM,1)  .NE.  0) THEN
            INBREF(LJNUM,1)= PININ(1)
            INBREFQ(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (INBREFQ(LJNUM,2)  .NE.  0) THEN
            INBREF(LJNUM,2)= PININ(2)
            INBREFQ(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (INBREFQ(LJNUM,3)  .NE.  0) THEN
            INBREF(LJNUM,3)= PININ(3)
            INBREFQ(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
        IF (PINNO  .EQ.  5) THEN
          IF (BODYPINQ(LJNUM,1)  .NE.  0) THEN
            BODYPIN(LJNUM,1)= PININ(1)
            BODYPINQ(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (BODYPINQ(LJNUM,2)  .NE.  0) THEN
            BODYPIN(LJNUM,2)= PININ(2)
            BODYPINQ(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (BODYPINQ(LJNUM,3)  .NE.  0) THEN
            BODYPIN(LJNUM,3)= PININ(3)
            BODYPINQ(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
        IF (PINNO  .EQ.  6) THEN
          IF (BODYREFQ(LJNUM,1)  .NE.  0) THEN
            BODYREF(LJNUM,1)= PININ(1)
            BODYREFQ(LJNUM,1)= 3
            ANYQUES= 1
          ENDIF
          IF (BODYREFQ(LJNUM,2)  .NE.  0) THEN
            BODYREF(LJNUM,2)= PININ(2)
            BODYREFQ(LJNUM,2)= 3
            ANYQUES= 1
          ENDIF
          IF (BODYREFQ(LJNUM,3)  .NE.  0) THEN
            BODYREF(LJNUM,3)= PININ(3)
            BODYREFQ(LJNUM,3)= 3
            ANYQUES= 1
          ENDIF
        ENDIF
      ELSE
        OFFS= FIRSTQ(JOINT)+PINNO-1
        IF (JTYPE(JOINT) .EQ. 21) THEN
          OFFS= OFFS+3
        ENDIF
        IF (JTYPE(JOINT) .EQ. 11) THEN
          OFFS= OFFS+1
        ENDIF
        IF (PINQ(OFFS,1)  .NE.  0) THEN
          PIN(OFFS,1)= PININ(1)
          PINQ(OFFS,1)= 3
          ANYQUES= 1
        ENDIF
        IF (PINQ(OFFS,2)  .NE.  0) THEN
          PIN(OFFS,2)= PININ(2)
          PINQ(OFFS,2)= 3
          ANYQUES= 1
        ENDIF
        IF (PINQ(OFFS,3)  .NE.  0) THEN
          PIN(OFFS,3)= PININ(3)
          PINQ(OFFS,3)= 3
          ANYQUES= 1
        ENDIF
      ENDIF
      IF (ANYQUES .EQ. 0) THEN
        CALL SDSETERR(6,19)
      ENDIF
      ROUSTATE= 0
C
      RETURN
      END
C
      SUBROUTINE SDPRES(JOINT,AXIS,PRESIN)
      INTEGER JOINT,AXIS,PRESIN
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER SDINDX,ANYQUES
      INTEGER SDCHKJAXIS
C
      IF (SDCHKJAXIS(37,JOINT,AXIS) .NE. 0) THEN
        RETURN
      ENDIF
      IF ((PRESIN .NE. 0) .AND. (PRESIN .NE. 1)) THEN
        CALL SDSETERR(37,20)
      ENDIF
      ANYQUES= 0
      IF (JOINT  .GT.  5) THEN
        IF (LPRESQ(SDINDX(JOINT,AXIS))  .NE.  0) THEN
          IF (PRESIN  .NE.  0) THEN
            LPRES(SDINDX(JOINT,AXIS))= 1D0
          ELSE
            LPRES(SDINDX(JOINT,AXIS))= 0D0
          ENDIF
          LPRESQ(SDINDX(JOINT,AXIS))= 3
          ANYQUES= 1
        ENDIF
      ELSE
        IF (PRESQ(SDINDX(JOINT,AXIS))  .NE.  0) THEN
          IF (PRESIN  .NE.  0) THEN
            PRES(SDINDX(JOINT,AXIS))= 1D0
          ELSE
            PRES(SDINDX(JOINT,AXIS))= 0D0
          ENDIF
          PRESQ(SDINDX(JOINT,AXIS))= 3
          ANYQUES= 1
        ENDIF
      ENDIF
      IF (ANYQUES .EQ. 0) THEN
        CALL SDSETERR(37,19)
      ENDIF
      WWFLG= 0
C
      RETURN
      END
