      SUBROUTINE SDGETPIN(JOINT,PINNO,PINOUT)
      INTEGER JOINT,PINNO
      DOUBLE PRECISION PINOUT(3)
C
      INTEGER GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,NLBALL,
     & NPRES,NUSER
      INTEGER JTYPE(7),INB(7),OUTB(7),NJNTDOF(7),NJNTC(7),NJNTP(7),
     & FIRSTQ(7),BALLQ(7),FIRSTM(7),FIRSTP(7)
      INTEGER TRANS(7)
      COMMON/SDGTOPO/ GROUND,NBOD,NDOF,NCONS,NLOOP,NLDOF,NLOOPC,NBALL,
     & NLBALL,NPRES,NUSER,JTYPE,INB,OUTB,NJNTDOF,NJNTC,NJNTP,FIRSTQ,
     & BALLQ,FIRSTM,FIRSTP,TRANS
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER LJNUM,OFFS
      INTEGER SDCHKJPIN
C
      IF (SDCHKJPIN(44,JOINT,PINNO) .NE. 0) THEN
        RETURN
      ENDIF
      IF (JOINT  .GT.  5) THEN
        LJNUM= JOINT-5
        IF (PINNO  .EQ.  1) THEN
          PINOUT(1)= INBPIN1(LJNUM,1)
          PINOUT(2)= INBPIN1(LJNUM,2)
          PINOUT(3)= INBPIN1(LJNUM,3)
        ENDIF
        IF (PINNO  .EQ.  2) THEN
          PINOUT(1)= INBPIN2(LJNUM,1)
          PINOUT(2)= INBPIN2(LJNUM,2)
          PINOUT(3)= INBPIN2(LJNUM,3)
        ENDIF
        IF (PINNO  .EQ.  3) THEN
          PINOUT(1)= INBPIN3(LJNUM,1)
          PINOUT(2)= INBPIN3(LJNUM,2)
          PINOUT(3)= INBPIN3(LJNUM,3)
        ENDIF
        IF (PINNO  .EQ.  4) THEN
          PINOUT(1)= INBREF(LJNUM,1)
          PINOUT(2)= INBREF(LJNUM,2)
          PINOUT(3)= INBREF(LJNUM,3)
        ENDIF
        IF (PINNO  .EQ.  5) THEN
          PINOUT(1)= BODYPIN(LJNUM,1)
          PINOUT(2)= BODYPIN(LJNUM,2)
          PINOUT(3)= BODYPIN(LJNUM,3)
        ENDIF
        IF (PINNO  .EQ.  6) THEN
          PINOUT(1)= BODYREF(LJNUM,1)
          PINOUT(2)= BODYREF(LJNUM,2)
          PINOUT(3)= BODYREF(LJNUM,3)
        ENDIF
      ELSE
        OFFS= FIRSTQ(JOINT)+PINNO-1
        IF (JTYPE(JOINT) .EQ. 21) THEN
          OFFS= OFFS+3
        ENDIF
        IF (JTYPE(JOINT) .EQ. 11) THEN
          OFFS= OFFS+1
        ENDIF
        PINOUT(1)= PIN(OFFS,1)
        PINOUT(2)= PIN(OFFS,2)
        PINOUT(3)= PIN(OFFS,3)
      ENDIF
C
      RETURN
      END
C
      SUBROUTINE SDGETPRES(JOINT,AXIS,PRESOUT)
      INTEGER JOINT,AXIS,PRESOUT
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
      INTEGER SDINDX
      INTEGER SDCHKJAXIS
C
      IF (SDCHKJAXIS(45,JOINT,AXIS) .NE. 0) THEN
        RETURN
      ENDIF
      IF (JOINT  .GT.  5) THEN
        IF (LPRES(SDINDX(JOINT,AXIS))  .NE.  0D0) THEN
          PRESOUT= 1
        ELSE
          PRESOUT= 0
        ENDIF
      ELSE
        IF (PRES(SDINDX(JOINT,AXIS))  .NE.  0D0) THEN
          PRESOUT= 1
        ELSE
          PRESOUT= 0
        ENDIF
      ENDIF
C
      RETURN
      END
C
      SUBROUTINE SDGETSTAB(VELOUT,POSOUT)
      DOUBLE PRECISION VELOUT,POSOUT
C
      DOUBLE PRECISION GRAV(3),MK(5),IK(5,3,3),PIN(5,3)
      DOUBLE PRECISION RK(5,3),RI(5,3),PRES(5),STABVEL,STABPOS
      DOUBLE PRECISION INBPIN1(2,3),INBPIN2(2,3),INBPIN3(2,3),INBREF(2,3
     & )
      DOUBLE PRECISION BODYPIN(2,3),BODYREF(2,3),LBTJ(2,3),LITJ(2,3),
     & LPRES(2)
      INTEGER MFRCFLG,ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,
     & LTAUFLG,FS0FLG,II,MMAP(5)
      INTEGER GRAVQ(3),MKQ(5),IKQ(5,3,3),PINQ(5,3),RKQ(5,3),RIQ(5,3),
     & PRESQ(5),STABVELQ,STABPOSQ
      INTEGER INBPIN1Q(2,3),INBPIN2Q(2,3),INBPIN3Q(2,3),INBREFQ(2,3),
     & BODYPINQ(2,3),BODYREFQ(2,3),LBTJQ(2,3),LITJQ(2,3),LPRESQ(2)
      DOUBLE PRECISION MTOT,PSMKG,RHEAD(5,3),RCOM(5,3),MKRCOMT(5,3,3),
     & PSIKG(3,3),PSRCOMG(3),PSRKG(3),PSRIG(3),PSMK(5),PSIK(5,3,3),
     & PSRCOM(5,3),PSRK(5,3),PSRI(5,3)
      DOUBLE PRECISION IPIN(2,3),IPIN2(2,3),IREF(2,3),IPERP(2,3),OPIN(2,
     & 3),OREF(2,3),OPERP(2,3),GHAND(2)
      COMMON/SDGINPUT/ GRAV,MK,IK,PIN,RK,RI,PRES,STABVEL,STABPOS,RHEAD,
     & RCOM,PSRCOMG,PSRCOM,MKRCOMT,PSMK,PSIK,PSRK,PSRI,PSMKG,PSIKG,PSRKG
     & ,PSRIG,MTOT,INBPIN1,INBPIN2,INBPIN3,INBREF,BODYPIN,BODYREF,LBTJ,
     & LITJ,LPRES,IPIN,IPIN2,IREF,IPERP,OPIN,OREF,OPERP,GHAND,MFRCFLG,
     & ROUSTATE,VPKFLG,INERFLG,MMFLG,MMLDUFLG,WWFLG,LTAUFLG,FS0FLG,II,
     & MMAP,GRAVQ,MKQ,IKQ,PINQ,RKQ,RIQ,PRESQ,STABVELQ,STABPOSQ,LBTJQ,
     & LITJQ,LPRESQ,INBPIN1Q,INBPIN2Q,INBPIN3Q,INBREFQ,BODYPINQ,BODYREFQ
C
      VELOUT= STABVEL
      POSOUT= STABPOS
